import re, glob, os, subprocess
root = '/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs'
docs = root + '/docs/site/src/content/docs/'
pages = []
for pat in ['getting-started/*.mdx', 'projects/*.mdx', 'assistant/*.mdx']:
    pages += glob.glob(docs + pat)
for p in ['settings', 'remembered-choices', 'file-locations', 'framejob-package', 'troubleshooting', 'glossary']:
    pages.append(docs + 'reference/' + p + '.mdx')
pages += [docs + 'mcp/tools-projects.mdx', docs + 'mcp/tools-media.mdx']

src = ''
for f in glob.glob(root + '/app/Sources/*.swift'):
    src += open(f, encoding='utf8').read()

# menu paths
seen = {}
for p in pages:
    t = open(p, encoding='utf8').read()
    for m in re.finditer(r"\*\*((?:File|Edit|View|Clip|Mark|Window|Insert|Help|Frame Job) ▸[^*]*)\*\*", t):
        seen.setdefault(m.group(1).strip(), set()).add(os.path.relpath(p, docs))
    for m in re.finditer(r"['\"]((?:File|Edit|View|Clip|Mark|Window|Insert|Help|Frame Job) ▸[^'\"]*)['\"]", t):
        seen.setdefault(m.group(1).strip(), set()).add(os.path.relpath(p, docs))
for k in sorted(seen):
    last = k.split('▸')[-1].strip() or k.split('▸')[-2].strip()
    found = ('"%s' % last) in src
    print(('OK  ' if found else 'MISS'), k, sorted(seen[k])[:3] if not found else '')

# tools
tools = set(re.findall(r'tool\(\s*"([a-z_0-9]+)"', src)) | set(re.findall(r'opTool\(\s*"([a-z_0-9]+)"', src))
print(len(tools))
used = {}
for p in pages:
    t = open(p, encoding='utf8').read()
    for m in re.finditer(r"`([a-z]+_[a-z_]+)`", t):
        used.setdefault(m.group(1), set()).add(os.path.relpath(p, docs))
    for m in re.finditer(r"tools=\{\[([^\]]*)\]\}", t):
        for n in re.findall(r"'([a-z_]+)'", m.group(1)):
            used.setdefault(n, set()).add(os.path.relpath(p, docs))
for n in sorted(used):
    if n not in tools:
        print('notool', n, sorted(used[n])[:2])

